const ClassSchema* find_class_schema(std::string_view name) { return find(kByName, name); }

const ClassSchema* find_component_schema(std::string_view component_name) {
    return find(kComponents, component_name);
}

std::span<const ClassSchema* const> all_class_schemas() { return kAll; }

